<script setup lang="ts">
// Review: what the agent has changed, before it is anybody's pull request.
//
// The PR tab is GitHub's view of a branch somebody pushed. This is the view before that: every
// change on the branch the agent is working on, committed or not, read straight out of the
// checkout the agent works in and drawn the way the PR tab draws a diff. Comments here are not
// kept anywhere - they are the next thing said to the agent. Write a few against the lines they
// are about, press send, and they go into a conversation in this workspace as one prompt: fix
// these, or answer these. The agent's reply is the pane docked above the diff.
import {
  computed, onBeforeUnmount, onMounted, reactive, ref, watch
} from 'vue';
import { Banner } from '@components/Banner';
import StudioTerminal from './StudioTerminal.vue';
import { vGrow } from './pr/grow';
import PrButton from './pr/PrButton.vue';
import PrBadge from './pr/PrBadge.vue';
import {
  parseHunks, highlightRows, hl
} from './pr/diff';
import type { DiffRow } from './pr/diff';
import CodeView from './code/CodeView.vue';
import { fromDiffRows } from './code/rows';
import type { CodeRow } from './code/rows';
import { listConversations, startConversation, queuePrompt, paneCommand } from '../conversations';
import type { ConversationOrigin } from '../agent';
import type { ProjectConversation } from '../conversations';
import { readInWorkspace, ensureWorkspaceReady } from '../workspace-tools';
import { everyWhileShown } from '../read-pacing.mjs';
import { workspaceRepo } from '../workspace-status';
import { workspaceWorkdir } from '../config/constants';
import { DEFAULT_REPO } from '../reviews';
import { useStore } from 'vuex';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Json = any;

const props = defineProps<{ workspace: Json }>();
const store = useStore();

const REFRESH_MS = 15000;

interface ChangedFile {
  path: string;
  status: 'added' | 'removed' | 'modified' | 'renamed';
  additions: number;
  deletions: number;
  patch: string;
  binary: boolean;
}

const repo = ref(DEFAULT_REPO);
const branch = ref('');
const base = ref('');
const files = ref<ChangedFile[]>([]);
const loading = ref(true);
const error = ref('');
const missing = ref('');
// The branch's commits (newest first), and what the diff is taken between. Empty selections mean
// the defaults: base = where the branch left master, head = the working tree (all changes,
// committed or not). Picking a commit narrows it. `defaultBase` is the merge-base shown as the
// "master" option.
const commits = ref<{ sha: string; subject: string }[]>([]);
const defaultBase = ref('');
const selectedBase = ref('');
const selectedHead = ref('');
const SHA_RE = /^[0-9a-f]{7,40}$/;
let stopBeat: (() => void) | null = null;

async function resolveRepo() {
  repo.value = await workspaceRepo(store, props.workspace);
}

/** Where the agents work: the workspace's own checkout, which is where its dev server runs from too. */
const dir = computed(() => workspaceWorkdir(props.workspace.name));

/**
 * The changes, read out of the clone: the branch against where it left the default branch,
 * plus whatever is not committed, plus files git does not know about yet.
 */
async function readChanges() {
  // Only ever hex commit ids from the list below reach the shell; anything else falls back to the
  // default (merge-base for the base, the working tree for the head).
  const baseSel = SHA_RE.test(selectedBase.value) ? selectedBase.value : '';
  const headSel = SHA_RE.test(selectedHead.value) ? selectedHead.value : '';
  // Head unset means the working tree: the committed diff plus what is staged, unstaged and
  // untracked. A chosen head is a plain commit-to-commit diff, so the untracked sweep is dropped.
  const diffCmd = headSel
    ? `git -c core.quotepath=off diff --no-color --no-ext-diff "$base" ${ headSel } 2>/dev/null`
    : 'git -c core.quotepath=off diff --no-color --no-ext-diff "$base" 2>/dev/null; for f in $(git ls-files --others --exclude-standard | head -40); do git -c core.quotepath=off diff --no-color --no-index /dev/null "$f" 2>/dev/null; done';
  const script = [
    `cd ${ dir.value } 2>/dev/null || { echo "@@NOREPO"; exit 0; }`,
    // upstream is rancher/dashboard once workspace-tools has set the remotes; before that it is
    // origin, and a checkout with neither is diffed against itself.
    'default_base=$(git merge-base upstream/master HEAD 2>/dev/null || git merge-base origin/master HEAD 2>/dev/null || git merge-base origin/HEAD HEAD 2>/dev/null || git rev-parse HEAD)',
    `base=${ baseSel || '$default_base' }`,
    'echo "@@BRANCH $(git rev-parse --abbrev-ref HEAD 2>/dev/null)"',
    'echo "@@DEFAULTBASE $default_base"',
    'echo "@@BASE $base"',
    // The branch's own commits, newest first, for the base/compare pickers.
    'echo "@@COMMITS"',
    'git log --format="%H%x09%s" "$default_base"..HEAD 2>/dev/null | head -100',
    'echo "@@ENDCOMMITS"',
    diffCmd,
    'echo "@@END"',
  ].join('; ');
  let out = '';

  try {
    out = await readInWorkspace(props.workspace.name, script);
  } catch (e: Json) {
    missing.value = e?.message || String(e);

    return;
  }

  if (out.includes('@@NOREPO')) {
    missing.value = `There is no checkout of ${ repo.value } in the workspace yet - it is cloned when the workspace starts.`;
    files.value = [];

    return;
  }
  missing.value = '';
  branch.value = /@@BRANCH (.*)/.exec(out)?.[1]?.trim() || '';
  defaultBase.value = /@@DEFAULTBASE (.*)/.exec(out)?.[1]?.trim() || '';
  base.value = /@@BASE (.*)/.exec(out)?.[1]?.trim() || '';

  const commitBlock = out.slice(out.indexOf('@@COMMITS') + '@@COMMITS'.length, out.indexOf('@@ENDCOMMITS'));

  commits.value = commitBlock.split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const [sha, ...rest] = line.split('\t');

      return { sha, subject: rest.join('\t') };
    })
    .filter((commit) => SHA_RE.test(commit.sha));

  const diffStart = out.indexOf('@@ENDCOMMITS') + '@@ENDCOMMITS'.length;
  const diffEnd = out.indexOf('@@END', diffStart);

  files.value = parseDiff(out.slice(diffStart, diffEnd >= 0 ? diffEnd : undefined));
}

/** git's unified diff, split into the shape the PR tab draws: one entry per file with its patch. */
function parseDiff(text: string): ChangedFile[] {
  const out: ChangedFile[] = [];
  const chunks = text.split(/^diff --git /m).slice(1);

  for (const chunk of chunks) {
    const lines = chunk.split('\n');
    const head = lines[0] || '';
    const m = /^"?a\/(.*?)"? "?b\/(.*?)"?$/.exec(head) || /^(\S+) (\S+)$/.exec(head);
    let path = (m?.[2] || m?.[1] || head).replace(/^"?b\//, '').replace(/"$/, '');

    if (path === '/dev/null') {
      path = (m?.[1] || '').replace(/^a\//, '');
    }
    const meta = lines.slice(1);
    const status: ChangedFile['status'] = meta.some((l) => l.startsWith('new file mode') || l.startsWith('--- /dev/null')) ? 'added'
      : meta.some((l) => l.startsWith('deleted file mode') || l.startsWith('+++ /dev/null')) ? 'removed'
        : meta.some((l) => l.startsWith('rename from')) ? 'renamed' : 'modified';
    const at = meta.findIndex((l) => l.startsWith('@@'));
    const patch = at === -1 ? '' : meta.slice(at).join('\n').replace(/\n$/, '');
    const binary = meta.some((l) => /^Binary files/.test(l));
    const additions = (patch.match(/^\+(?!\+\+)/gm) || []).length;
    const deletions = (patch.match(/^-(?!--)/gm) || []).length;

    out.push({
      path: path.replace(/^\.\//, ''), status, additions, deletions, patch, binary,
    });
  }

  return out.sort((a, b) => a.path.localeCompare(b.path));
}

interface RowView { row: DiffRow }
interface FileView { file: ChangedFile; rows: RowView[]; code: CodeRow[] }

/**
 * Each file's diff, twice: as this tab's own rows, and as the shared view's.
 *
 * `code` is what is drawn (see components/code/CodeView.vue, which every diff in this extension
 * now goes through) and each of its rows carries the `DiffRow` it came from in `meta`, so a click
 * still arrives at `lineClick` with the row it has always taken.
 */
const fileViews = computed<FileView[]>(() => files.value.map((file) => {
  const rows: DiffRow[] = parseHunks(file.patch).flatMap((h) => h.rows);

  highlightRows(file.path, rows);

  // Highlighted into `hl()`'s map above, so the html is pulled from there rather than computed
  // a second time.
  const code: CodeRow[] = fromDiffRows(rows).map((row, n) => ({
    ...row,
    html: rows[n].type === 'hunk' ? undefined : hl(rows[n]),
  }));

  return { file, rows: rows.map((row) => ({ row })), code };
}));

const totals = computed(() => ({
  additions: files.value.reduce((t, f) => t + f.additions, 0),
  deletions: files.value.reduce((t, f) => t + f.deletions, 0),
}));

const collapsed = reactive(new Set<string>());
const fileEls = new Map<string, HTMLElement>();

function setFileEl(path: string, el: unknown) {
  if (el instanceof HTMLElement) {
    fileEls.set(path, el);
  } else {
    fileEls.delete(path);
  }
}

function scrollToFile(path: string) {
  collapsed.delete(path);
  requestAnimationFrame(() => fileEls.get(path)?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
}

// ── Notes: click a line, say something about it ──
const composer = ref<{ path: string; side: 'LEFT' | 'RIGHT'; line: number; code: string } | null>(null);
const composerDraft = ref('');

function lineClick(path: string, row: DiffRow) {
  const side: 'LEFT' | 'RIGHT' | null = row.newN != null ? 'RIGHT' : row.oldN != null ? 'LEFT' : null;

  if (!side) {
    return;
  }
  const line = (side === 'RIGHT' ? row.newN : row.oldN)!;

  if (composer.value && composer.value.path === path && composer.value.line === line && composer.value.side === side) {
    composer.value = null;

    return;
  }
  composer.value = {
    path, side, line, code: row.text,
  };
  composerDraft.value = '';
}

function composerMatches(path: string, row: DiffRow): boolean {
  const c = composer.value;

  return !!c && c.path === path && (c.side === 'RIGHT' ? row.newN === c.line : row.oldN === c.line);
}

// A question, or a remark about the whole change, with no line to hang it on.
const general = ref('');

// ── Sending it to the agent ──
// One comment, one send. Each line's dialog (and the whole-change box) carries its own conversation
// picker and Send: the person writes the comment against the code, chooses a new or existing
// conversation right there, and it goes as one prompt. There is no basket of unsent notes and no
// separate send button at the top - a comment is the next thing said to the agent, said when it is
// written.
const conversations = ref<ProjectConversation[]>([]);
const target = ref('new');
const session = ref('');
const sending = ref(false);
const showPane = ref(false);

async function loadConversations() {
  conversations.value = await listConversations(props.workspace.name).catch(() => []);
}

/** The standing instruction that frames whatever one comment says. */
function intro(): string {
  return `Review feedback on your changes on branch ${ branch.value || '(current)' } in ${ dir.value }, from the person reviewing them in the Rancher dashboard. Address it: make the change if it asks for one, answer it here if it is a question, and say what you did. Do not open a pull request unless asked.`;
}

/**
 * Send one message to the chosen conversation (a new one, or an existing one), and show its pane.
 *
 * `from` is where the comment was written - a file and a line, or the whole-change box - and it
 * goes into the new conversation's id, so "Review feedback" is no longer five conversations with
 * one name between them. See conversation-id.mjs.
 */
async function sendText(text: string, from: ConversationOrigin = ''): Promise<boolean> {
  if (sending.value) {
    return false;
  }
  sending.value = true;
  error.value = '';
  try {
    if (target.value === 'new') {
      await ensureWorkspaceReady(props.workspace.name);

      const conversation = await startConversation(props.workspace.name, 'Review feedback', text, '', from);

      session.value = conversation.id;
      // Keep sending to the conversation just made, so a second comment joins the first.
      target.value = conversation.id;
      await loadConversations();
    } else {
      const conversation = conversations.value.find((c) => c.id === target.value);

      if (!conversation) {
        throw new Error('That conversation is gone. Pick another, or a new one.');
      }
      await queuePrompt(conversation.attach, text);
      session.value = conversation.id;
    }
    showPane.value = true;
    store.dispatch('growl/success', { title: '', message: 'Sent to the agent. Its reply is the pane above the diff.', timeout: 4000 }, { root: true });

    return true;
  } catch (e: Json) {
    error.value = e?.message || String(e);

    return false;
  } finally {
    sending.value = false;
  }
}

/** Send the comment written against a line, then close its dialog. */
async function sendComposer() {
  const c = composer.value;
  const body = composerDraft.value.trim();

  if (!c || !body) {
    return;
  }
  const text = `${ intro() }\n\n${ c.path }:${ c.line }${ c.side === 'LEFT' ? ' (the removed line)' : '' } - on \`${ c.code.trim().slice(0, 160) }\`:\n${ body }`;

  if (await sendText(text, { path: c.path, line: c.line })) {
    composer.value = null;
    composerDraft.value = '';
  }
}

/** Send the whole-change note. */
async function sendGeneral() {
  const body = general.value.trim();

  if (!body) {
    return;
  }
  // The whole-change box is a place too, and a different one from any line in the diff.
  if (await sendText(`${ intro() }\n\n${ body }`, 'review-whole-change')) {
    general.value = '';
  }
}

function fileTone(f: ChangedFile): string {
  return f.status === 'added' ? 'success' : f.status === 'removed' ? 'error' : 'neutral';
}

async function refresh() {
  try {
    await readChanges();
    error.value = '';
  } catch (e: Json) {
    error.value = e?.message || String(e);
  } finally {
    loading.value = false;
  }
}

function shortSha(sha: string): string {
  return (sha || '').slice(0, 7);
}

// Re-read the diff the moment the base or compare point changes, rather than waiting for the poll.
watch([selectedBase, selectedHead], () => {
  loading.value = true;
  refresh();
});

onMounted(async() => {
  await resolveRepo();
  await Promise.all([refresh(), loadConversations()]);
  stopBeat = everyWhileShown(() => refresh(), REFRESH_MS);
});

onBeforeUnmount(() => {
  stopBeat?.();
});

defineExpose({ refresh });
</script>

<template>
  <div class="pr-review workspace-review">
    <header class="prm-header">
      <div class="prm-header-row">
        <div class="prm-title">
          <PrBadge :tone="files.length ? 'accent' : 'neutral'">
            {{ branch || 'no branch' }}
          </PrBadge>
          <span class="prm-title-text">{{ repo }}</span>
          <span
            v-if="files.length"
            class="muted prm-title-sub"
          >{{ files.length }} file{{ files.length === 1 ? '' : 's' }} changed · <span class="add-count">+{{ totals.additions }}</span> <span class="del-count">−{{ totals.deletions }}</span></span>
        </div>
        <div class="prm-actions">
          <PrButton
            v-if="session"
            size="sm"
            :variant="showPane ? 'accent' : 'default'"
            @click="showPane = !showPane"
          >
            {{ showPane ? 'Hide agent' : 'Show agent' }}
          </PrButton>
          <PrButton
            size="sm"
            @click="refresh"
          >
            Refresh
          </PrButton>
        </div>
      </div>
      <div class="prm-meta">
        <label class="prm-compare">
          <span class="muted">Diff</span>
          <select
            v-model="selectedBase"
            title="What to diff from"
          >
            <option value="">
              master (branch start)
            </option>
            <option
              v-for="c in commits"
              :key="`b-${ c.sha }`"
              :value="c.sha"
            >
              {{ shortSha(c.sha) }} · {{ c.subject }}
            </option>
          </select>
          <span class="muted">→</span>
          <select
            v-model="selectedHead"
            title="What to compare"
          >
            <option value="">
              working tree (all changes)
            </option>
            <option
              v-for="c in commits"
              :key="`h-${ c.sha }`"
              :value="c.sha"
            >
              {{ shortSha(c.sha) }} · {{ c.subject }}
            </option>
          </select>
        </label>
        <span class="muted prm-meta-note">Read from the agent's checkout in {{ dir }}. Comments are not kept: they are the next thing said to the agent.</span>
      </div>
    </header>

    <div
      v-if="showPane && session"
      class="prm-review-panel"
    >
      <div class="review-panel-header">
        <span class="review-panel-title">Agent</span>
        <span class="review-panel-sub">conversation {{ session }} in {{ workspace.name }}</span>
        <PrButton
          variant="ghost"
          size="mini"
          class="prm-close"
          @click="showPane = false"
        >
          &times;
        </PrButton>
      </div>
      <StudioTerminal
        :key="session"
        :session="session"
        :command="paneCommand(workspace.name, session)"
        class="review-term"
      />
    </div>

    <Banner
      v-if="error"
      color="error"
      :label="error"
      class="prm-banner"
    />
    <Banner
      v-else-if="missing"
      color="info"
      :label="missing"
      class="prm-banner"
    />
    <div
      v-else-if="loading"
      class="prm-loading"
    >
      Reading the checkout…
    </div>
    <div
      v-else-if="!files.length"
      class="prm-loading"
    >
      Nothing has changed on {{ branch || 'this branch' }} yet.
    </div>

    <div
      v-if="files.length"
      class="prm-main"
    >
      <aside class="prm-filenav">
        <div
          v-for="fv in fileViews"
          :key="fv.file.path"
          class="filenav-item"
          :title="fv.file.path"
          @click="scrollToFile(fv.file.path)"
        >
          <span class="filenav-name">{{ fv.file.path }}</span>
          <span class="filenav-icons">
            <span class="add-count">+{{ fv.file.additions }}</span>
            <span class="del-count">−{{ fv.file.deletions }}</span>
          </span>
        </div>
      </aside>

      <div class="prm-body">
        <!-- A question, or a remark about the whole change. -->
        <section class="prm-prlevel">
          <div class="prlevel-head">
            <PrBadge tone="accent">
              To the agent
            </PrBadge>
            <span class="muted">A question about the change, or a note that is not about one line.</span>
          </div>
          <div class="prlevel-compose">
            <textarea
              v-model="general"
              v-grow
              class="edit-textarea"
              rows="2"
              placeholder="Why did you change the validator this way? / Please also cover the IPv6 zone-id case."
              @keydown.enter.ctrl.prevent="sendGeneral"
            />
            <div class="wr-send-row">
              <select
                v-model="target"
                class="review-target"
                title="Which conversation this goes to"
              >
                <option value="new">
                  A new conversation
                </option>
                <option
                  v-for="c in conversations"
                  :key="c.id"
                  :value="c.id"
                >
                  {{ c.title }}
                </option>
              </select>
              <PrButton
                size="sm"
                variant="primary"
                :disabled="!general.trim() || sending"
                @click="sendGeneral"
              >
                {{ sending ? 'Sending…' : 'Send to the agent' }}
              </PrButton>
            </div>
          </div>
        </section>

        <div
          v-for="fv in fileViews"
          :key="fv.file.path"
          :ref="(el) => setFileEl(fv.file.path, el)"
          class="prm-file"
        >
          <div
            class="file-header clickable"
            @click="collapsed.has(fv.file.path) ? collapsed.delete(fv.file.path) : collapsed.add(fv.file.path)"
          >
            <span
              class="collapse-chevron"
              :class="{ collapsed: collapsed.has(fv.file.path) }"
            >▾</span>
            <span class="file-path">{{ fv.file.path }}</span>
            <span class="file-stats">
              <PrBadge :tone="fileTone(fv.file)">
                {{ fv.file.status }}
              </PrBadge>
              <span class="add-count">+{{ fv.file.additions }}</span>
              <span class="del-count">−{{ fv.file.deletions }}</span>
            </span>
          </div>
          <CodeView
            v-if="fv.file.patch && !collapsed.has(fv.file.path)"
            :rows="fv.code"
            selectable
            @pick="(range) => lineClick(fv.file.path, fv.code[range[0]].meta as DiffRow)"
          >
            <!-- The composer, under the line it is about: what the table's `comment-row` was. -->
            <template #after="{ row }">
              <div
                v-if="composerMatches(fv.file.path, row.meta as DiffRow)"
                class="wr-anchored"
              >
                <div class="comment composer-card">
                <div class="comment-head">
                  <span class="comment-author">To the agent — L{{ composer!.line }}</span>
                </div>
                <textarea
                  v-model="composerDraft"
                  v-grow
                  class="edit-textarea"
                  placeholder="What should change here, or what do you want to know about it?"
                  @keydown.esc.prevent="composer = null"
                  @keydown.enter.ctrl.prevent="sendComposer"
                />
                <div class="edit-btns wr-send-row">
                  <select
                    v-model="target"
                    class="review-target"
                    title="Which conversation this goes to"
                  >
                    <option value="new">
                      A new conversation
                    </option>
                    <option
                      v-for="c in conversations"
                      :key="c.id"
                      :value="c.id"
                    >
                      {{ c.title }}
                    </option>
                  </select>
                  <PrButton
                    size="mini"
                    class="approve"
                    :disabled="!composerDraft.trim() || sending"
                    @click="sendComposer"
                  >
                    {{ sending ? 'Sending…' : 'Send to the agent' }}
                  </PrButton>
                  <PrButton
                    size="mini"
                    @click="composer = null"
                  >
                    Cancel
                  </PrButton>
                  </div>
                </div>
              </div>
            </template>
          </CodeView>
          <div
            v-else-if="!collapsed.has(fv.file.path)"
            class="muted no-patch"
          >
            {{ fv.file.binary ? 'Binary file.' : 'No diff to show.' }}
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<style lang="scss" scoped src="./pr/panel.scss"></style>
<style lang="scss" scoped>
// What `.comment-row td` used to give the composer, now that it hangs under the line rather than
// inside a table cell. See components/code/CodeView.vue and its `after` slot.
.wr-anchored { padding: var(--dev-space-2) var(--dev-space-5); }

.review-target {
  height:    28px;
  padding:   0 var(--dev-space-3);
  font-size: 12px;
  max-width: 220px;
}

// Where a comment chooses its conversation and is sent - in the dialog itself, not at the top.
.wr-send-row {
  display:     flex;
  align-items: center;
  gap:         var(--dev-space-3, 8px);
  flex-wrap:   wrap;
}

// The base -> compare pickers on the meta row.
.prm-compare {
  display:      inline-flex;
  align-items:  center;
  gap:          6px;
  margin-right: var(--dev-space-4, 12px);

  select {
    height:    24px;
    max-width: 280px;
    font-size: 12px;
  }
}

.prm-meta-note {
  font-size: 12px;
