import { importTypes } from '@rancher/auto-import';
/*
 * The product's stylesheets, from the entry point, because they are the product's and not any
 * one component's.
 *
 * They used to arrive as a side effect of importing design/tokens.ts, which three layout
 * components import - so whether a surface was styled depended on whether something on it
 * happened to use a Stack or a Row. The pages all do; the chat drawer mounts its own Vue app
 * on `document.body` and does not, which is how the phone pass came to miss the one surface
 * that most needed it. Here it is unconditional.
 */
import './design/tokens.css';
import './design/mobile.css';
import './design/login.css';
import { IPlugin, ActionLocation } from '@shell/core/types';
import routes from './routing';
import { stageResource } from './builder/state';
import { openBuilder, toggleBuilder, restoreBuilder } from './builder/overlay';
import { initPageMarks } from './builder/page-marks';
import { ADD_TO_APP_ACTION } from './config/types';
import { ensureAgent } from './agent';
import { registerAgentOverlay } from './overlay';
import { installBrowserApi } from './public-api';
import { keepThemeLocal } from './theme-local';
import { whenLoggedIn } from './dashboard-app';

// Init the package
export default function(plugin: IPlugin): void {
  // ── Agents ────────────────────────────────────────────────────────────────────────────────
  //
  // First, and before anything that needs a cluster: the API other code places a pane with has
  // to exist before the page that places one renders.
  //
  // This was its own extension until it was not. Nothing here could hold a conversation without
  // it - the agent pod, the pane behind every conversation, the terminal component the pages
  // embed, the seed each workspace copies - and Rancher has no way for one extension to depend
  // on another: the Extensions pages read no such annotation, and the chart is generated by a
  // pinned workflow of Rancher's with no room for a subchart. The choice was a page-load
  // installer that put the other extension there, or one bundle. This is one bundle.
  installBrowserApi(require('./package.json').version);

  // The one agent pod, and what it needs to exist first. Not until somebody is signed in: this
  // bundle is served to the login page too (`rancher.noAuth`), and a local login does not load it
  // again. Still caught, because not every person who signs in may create it.
  whenLoggedIn(() => {
    ensureAgent().catch(() => {});
  });

  // And the chord that opens a terminal into it, from any page in Rancher.
  registerAgentOverlay();

  // The theme belongs to this browser, not to the account every agent is signed in as. See
  // theme-pref.mjs: without this, an agent checking a bug in light mode turns the person's own
  // dashboard light, hours later, with nothing to point at.
  keepThemeLocal();

  // Auto-import model, detail, edit, list and l10n from the folders. Both products' types are
  // picked up by the one call: they are folders of one package now (see apps-plus.ts).
  importTypes(plugin);

  // Provide plugin metadata from package.json
  plugin.metadata = require('./package.json');

  plugin.addRoutes(routes);

  // The product module is passed whole, not its init function: addProduct treats any
  // argument with a truthy `.name` as the newer metadata API, and a named function has one.
  plugin.addProduct(require('./product'));

  // ── Apps Plus ─────────────────────────────────────────────────────────────────────────────
  //
  // Its own product still, rather than pages under Dev: Apps and Installations are the layer
  // Dev is built on and are worth looking at on their own terms - and the Ranchers in the Dev
  // sidebar are Installations of an App (`rancher-single`) that somebody edits here. What has
  // changed is only that installing one extension installs both.
  plugin.addProduct(require('./apps-plus-product'));

  // The builder's handle in the dashboard's own header, which is the only control that is not
  // attached to a page - the drawer it opens outlives every page, so its handle has to as well.
  plugin.addAction(ActionLocation.HEADER, {}, {
    labelKey:   'appsPlus.builder.title',
    tooltipKey: 'appsPlus.builder.title',
    icon:       'icon-archive',
    invoke:     () => toggleBuilder(),
  });

  /**
   * "Add to Application", on every resource there is: a table action is handed the selected
   * rows, so collecting eight Deployments into an App costs the same as one.
   */
  plugin.addAction(ActionLocation.TABLE, {}, {
    action:   ADD_TO_APP_ACTION,
    labelKey: 'appsPlus.builder.add',
    icon:     'icon-flask',
    multiple: true,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    invoke:   (_opts: any, resources: any[]) => {
      openBuilder();

      (resources || []).forEach((resource) => stageResource(resource));
    },
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } as any);

  // A drawer that was open when the page was left should be open when it comes back - to the
  // dashboard, not to the login page in front of it.
  whenLoggedIn(restoreBuilder);

  // The switches that appear on a staged resource's own edit page.
  initPageMarks();
}
